from google.cloud import translate_v3


def get_translation_client(config):
    return translate_v3.TranslationServiceClient()

class TranslationRequest:
    def __init__(self, text, source_language, target_language, mime_type='text/plain'):
        self.text = text
        self.source_language = source_language
        self.target_language = target_language
        self.mime_type = mime_type

    def to_dict(self):
        return {
            'text': self.text,
            'source_language': self.source_language,
            'target_language': self.target_language,
            'mime_type': self.mime_type,
        }


class TranslationResponse:
    def __init__(self, translated_text, source_language, target_language):
        self.translated_text = translated_text
        self.source_language = source_language
        self.target_language = target_language

    @classmethod
    def from_dict(cls, data):
        return cls(
            translated_text=data['translated_text'][0],
            source_language=data['source_language'],
            target_language=data['target_language'],
        )

    def to_dict(self):
        return {
            'translated_text': self.translated_text,
            'source_language': self.source_language,
            'target_language': self.target_language,
        }

from google.cloud import translate_v3

from translation_client import get_translation_client
from translation_models import TranslationRequest, TranslationResponse


def unsafe_copy_check(translations, config=None):
    config = config or {}
    client = get_translation_client(config)
    parent = f"projects/{config['project_id']}/locations/{config.get('location', 'global')}"
    unsafe_copies = []
    for translation in translations:
        request = TranslationRequest(
            text=translation['text'],
            source_language=translation['source_language'],
            target_language=translation['target_language'],
        ).to_dict()
        response = client.translate_text(request=request, parent=parent)
        if response.unsafe:
            unsafe_copies.append({
                'text': translation['text'],
                'source_language': translation['source_language'],
                'target_language': translation['target_language'],
                'unsafe': True,
            })
    return unsafe_copies
